query FindFluffyPokemon($fluffyPattern: String!, $languageId: Int!, $limit: Int!) {
  pokemonspecies(
    where: {
      pokemonspeciesflavortexts: {
        language_id: {_eq: $languageId}
        flavor_text: {_ilike: $fluffyPattern}
      }
    }
    order_by: {id: asc}
    limit: $limit
  ) {
    id
    name
    pokemonspeciesflavortexts(
      where: {
        language_id: {_eq: $languageId}
        flavor_text: {_ilike: $fluffyPattern}
      }
      limit: 1
    ) {
      flavor_text
    }
  }
}

